  // coingecko coin ids
  static const Map<Type, String> _coinToIdMap = {
    Bitcoin: "bitcoin",
    BitcoinFrost: "bitcoin",
    Litecoin: "litecoin",
    Bitcoincash: "bitcoin-cash",
    Cardano: "cardano",
    Dash: "dash",
    Dogecoin: "dogecoin",
    Pepecoin: "pepecoin-network",
    Bellscoin: "bellscoin",
    Epiccash: "epic-cash",
    Mimblewimblecoin: "mimblewimblecoin",
    Ecash: "ecash",
    Ethereum: "ethereum",
    Fact0rn: "fact0rn",
    Firo: "zcoin",
    Monero: "monero",
    Particl: "particl",
    Peercoin: "peercoin",
    Solana: "solana",
    Stellar: "stellar",
    Tezos: "tezos",
    Wownero: "wownero",
    Namecoin: "namecoin",
    Nano: "nano",
    Banano: "banano",
    Xelis: "xelis",
    Salvium: "salvium",
  };

  static const refreshInterval = 60;

  // initialize to older than current time minus at least refreshInterval
  static DateTime _lastCalled = DateTime.now().subtract(
    const Duration(seconds: refreshInterval + 10),
  );

  static String _lastUsedBaseCurrency = "";

  static const Duration refreshIntervalDuration = Duration(
    seconds: refreshInterval,
  );

  final HTTP client;

  PriceAPI(this.client);

  @visibleForTesting
  void resetLastCalledToForceNextCallToUpdateCache() {
    _lastCalled = DateTime(1970);
  }

  Future<void> _updateCachedPrices(
    Map<CryptoCurrency, ({Decimal value, double change24h})> data,
  ) async {
    final Map<String, dynamic> map = {};

    for (final coin in AppConfig.coins) {
      final entry = data[coin];
      if (entry == null) {
        map[coin.prettyName] = ["0", 0.0];
      } else {
        map[coin.prettyName] = [entry.value.toString(), entry.change24h];
      }
    }

    await DB.instance.put<dynamic>(
      boxName: DB.boxNamePriceCache,
      key: 'cache',
      value: map,
    );
  }

  Map<CryptoCurrency, ({Decimal value, double change24h})> get _cachedPrices {
    final map =
        DB.instance.get<dynamic>(boxName: DB.boxNamePriceCache, key: 'cache')
            as Map? ??
        {};
    // init with 0
    final Map<CryptoCurrency, ({Decimal value, double change24h})> result = {};

    for (final entry in map.entries) {
      result[AppConfig.getCryptoCurrencyByPrettyName(entry.key as String)] = (
        value: Decimal.parse(entry.value[0] as String),
        change24h: entry.value[1] as double,
      );
    }

    return result;
  }

  String get _coinIds => AppConfig.coins
      .where((e) => e.network == CryptoCurrencyNetwork.main)
      .map((e) => _coinToIdMap[e.runtimeType])
      .where((e) => e != null)
      .join(",");

  /// 7-day hourly price series per coin, from the same markets response.
  /// Absent for any coin the price API does not list — BFX has no market, so it
  /// has no series, and the UI must render nothing rather than an empty chart.
  final Map<CryptoCurrency, List<double>> sparklines = {};

  // Redesign: the hero chart gained 24H/30D ranges beside the bundled 7D
  // sparkline. Those need their own market_chart call, fetched lazily on
  // first selection and cached per coin+range+currency, because CoinGecko's
  // free tier rate-limits hard and the price poll already runs every minute.
  final Map<String, (DateTime, List<double>)> _marketChartCache = {};
  static const _marketChartCacheLife = Duration(minutes: 5);

  Future<List<double>?> getMarketChart({
    required CryptoCurrency coin,
    required int days,
    required String baseCurrency,
  }) async {
    final id = _coinToIdMap[coin.runtimeType];
    if (id == null) return null;

    final key = "$id:$days:${baseCurrency.toLowerCase()}";
    final cached = _marketChartCache[key];
    if (cached != null &&
        DateTime.now().difference(cached.$1) < _marketChartCacheLife) {
      return cached.$2;
    }

    try {
      final uri = Uri.parse(
        "https://api.coingecko.com/api/v3/coins/$id/market_chart"
        "?vs_currency=${baseCurrency.toLowerCase()}&days=$days",
      );

      final response = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final json = jsonDecode(response.body);
      final prices = json["prices"] as List?;
      if (prices != null && prices.length > 1) {
        final series = prices
            .map((e) => ((e as List)[1] as num).toDouble())
            .toList(growable: false);
        _marketChartCache[key] = (DateTime.now(), series);
        return series;
      }
    } catch (e, s) {
      Logging.instance.w(
        "getMarketChart($id, $days) failed",
        error: e,
        stackTrace: s,
      );
    }
    // A stale series beats an empty chart flash on a transient failure.
    return cached?.$2;
  }

  /// BFX price, from our own endpoint rather than CoinGecko.
  ///
  /// BFX is not on CoinGecko, so it was simply unpriced until it gained a
  /// market. This reads explorer.bitfinitechain.org, which proxies the
  /// exchange: the wallet polls every minute, and pointing every installation
  /// straight at the venue would hand it a view of our users.
  ///
  /// USD ONLY for now. The endpoint quotes BFX/USDT and does no currency
  /// conversion, so a wallet set to any other base currency keeps showing no
  /// BFX price, exactly as it did before. That is the honest failure: a number
  /// in the wrong currency is worse than no number.
  ///
  /// Returns null on any problem, which the caller treats as unpriced. Never
  /// returns zero: zero means "worthless" to every consumer downstream, and
  /// what we actually mean is "no price".
  static const _bfxPriceUrl = "https://explorer.bitfinitechain.org/api/price";

  Future<({Decimal value, double change24h, List<double> sparkline})?>
  _getBitfinitePrice({required String baseCurrency}) async {
    if (baseCurrency.toLowerCase() != "usd") return null;
    try {
      final response = await client.get(
        url: Uri.parse(_bfxPriceUrl),
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );
      if (response.code != 200) return null;

      final map = jsonDecode(response.body) as Map<String, dynamic>;
      final value = Decimal.tryParse(map["usd"].toString());
      if (value == null || value <= Decimal.zero) return null;

      // Absent until the market is genuinely a day old. The endpoint sends
      // null rather than dressing "change since listing" up as a 24h move.
      final change = (map["change24h"] as num?)?.toDouble() ?? 0.0;

      final series = (map["sparkline"] as List<dynamic>? ?? [])
          .map((e) => (e as num?)?.toDouble())
          .whereType<double>()
          .toList();

      return (value: value, change24h: change, sparkline: series);
    } catch (e, s) {
      Logging.instance.e("_getBitfinitePrice: ", error: e, stackTrace: s);
      return null;
    }
  }

  Future<Map<CryptoCurrency, ({Decimal value, double change24h})>>
  getPricesAnd24hChange({required String baseCurrency}) async {
    final now = DateTime.now();
    if (_lastUsedBaseCurrency != baseCurrency ||
        now.difference(_lastCalled) > refreshIntervalDuration) {
      _lastCalled = now;
      _lastUsedBaseCurrency = baseCurrency;
    } else {
      return _cachedPrices;
    }

    final externalCalls = Prefs.instance.externalCalls;
    if ((!Util.isTestEnv && !externalCalls) ||
        !(await Prefs.instance.isExternalCallsSet())) {
      Logging.instance.i("User does not want to use external calls");
      return _cachedPrices;
    }
    final Map<CryptoCurrency, ({Decimal value, double change24h})> result = {};
    try {
      final uri = Uri.parse(
        "https://api.coingecko.com/api/v3/coins/markets?vs_currency"
        "=${baseCurrency.toLowerCase()}&ids=$_coinIds&order=market_cap_desc"
        "&per_page=50&page=1&sparkline=true",
        // sparkline=true costs no extra request: CoinGecko returns
        // sparkline_in_7d (168 hourly points) inside this same response.
        // It does make each response noticeably larger, which is why the
        // series is only read here and not polled on its own timer.
      );

      final coinGeckoResponse = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final coinGeckoData = jsonDecode(coinGeckoResponse.body) as List<dynamic>;

      for (final map in coinGeckoData) {
        final String coinName = map["name"] as String;
        late CryptoCurrency coin;
        try {
          coin = AppConfig.getCryptoCurrencyByPrettyName(
            coinName == "Factor" ? "Fact0rn" : coinName,
          );
        } catch (e, s) {
          Logging.instance.e(
            "Failed to find matching app coin for $coinName. Moving on",
            error: e,
            stackTrace: s,
          );
          continue;
        }

        try {
          final price = Decimal.parse(map["current_price"].toString());
          final change24h = map["price_change_percentage_24h"] != null
              ? double.parse(map["price_change_percentage_24h"].toString())
              : 0.0;

          result[coin] = (value: price, change24h: change24h);

          // Kept in a separate map rather than widened into the record above:
          // that record's shape is depended on by 17 call sites, and none of
          // them want a price history.
          final spark = map["sparkline_in_7d"];
          if (spark is Map && spark["price"] is List) {
            final series = (spark["price"] as List)
                .map((e) => double.tryParse(e.toString()))
                .whereType<double>()
                .toList();
            if (series.length > 1) {
              sparklines[coin] = series;
            } else {
              sparklines.remove(coin);
            }
          }
        } catch (_) {
          result.remove(coin);
          sparklines.remove(coin);
        }
      }

      // BFX rides alongside rather than inside the CoinGecko response,
      // because it is not listed there. A failure here must not lose the
      // prices we just fetched, so it is deliberately not inside the try
      // that wraps the CoinGecko call.
      final bfx = await _getBitfinitePrice(baseCurrency: baseCurrency);
      if (bfx != null) {
        try {
          // "BitFinite" with the capital F is the real prettyName, so this
          // matches on both the exact name and the lowercased identifier.
          // The testnet coin is "tBitFinite"/"bitfiniteTestnet" and cannot
          // collide with it.
          final coin = AppConfig.getCryptoCurrencyByPrettyName("BitFinite");
          result[coin] = (value: bfx.value, change24h: bfx.change24h);
          if (bfx.sparkline.length > 1) {
            sparklines[coin] = bfx.sparkline;
          } else {
            sparklines.remove(coin);
          }
        } catch (e, s) {
          Logging.instance.e(
            "BFX price: no matching app coin",
            error: e,
            stackTrace: s,
          );
        }
      }

      // update cache
      await _updateCachedPrices(result);

      return _cachedPrices;
    } catch (e, s) {
      Logging.instance.e(
        "getPricesAnd24hChange($baseCurrency): ",
        error: e,
        stackTrace: s,
      );
      // return previous cached values
      return _cachedPrices;
    }
  }

  static Future<List<String>?> availableBaseCurrencies() async {
    final externalCalls = Prefs.instance.externalCalls;
    const client = HTTP();

    if ((!Util.isTestEnv && !externalCalls) ||
        !(await Prefs.instance.isExternalCallsSet())) {
      Logging.instance.i("User does not want to use external calls");
      return null;
    }
    const uriString =
        "https://api.coingecko.com/api/v3/simple/supported_vs_currencies";
    try {
      final uri = Uri.parse(uriString);
      final response = await client.get(
        url: uri,
        headers: {'Content-Type': 'application/json'},
        proxyInfo: !AppConfig.hasFeature(AppFeature.tor)
            ? null
            : Prefs.instance.useTor
            ? TorService.sharedInstance.getProxyInfo()
            : null,
      );

      final json = jsonDecode(response.body) as List<dynamic>;
      return List<String>.from(json);
    } catch (e, s) {
      Logging.instance.e(
        "availableBaseCurrencies() using $uriString: ",
        error: e,
        stackTrace: s,
      );
      return null;
    }
  }

